namespace HelixPythonNamespace.App
{
    using System;
    using System.Drawing;
    using System.Windows.Forms;
    using HelixPythonNamespace.Workspace.Toml;

    using HelixPythonNamespace.UI.Controls;
    /// <summary>
    /// FR-DES-05: a graphical TOML editor — a tree/form surface (not a graph) over a
    /// <see cref="TomlDocument"/>. The left <see cref="TreeView"/> shows tables, array-of-tables, and
    /// key/value pairs; selecting a scalar shows an editable key/value form; Add Table / Add Key / Remove
    /// mutate the model; the right pane shows the live TOML generated by <see cref="TomlWriter"/>. Launched
    /// from Tools ▸ TOML Designer. Completes the TOML column (parser/highlight/complete/lint/analyze/gen).
    /// </summary>
    public sealed class TomlDesignerForm : LunaForm
    {
        private static TomlDesignerForm _instance;

        private TomlDocument _doc = TomlParser.Parse(Sample);
        private readonly TreeView _tree;
        private readonly TextBox _keyBox;
        private readonly TextBox _valueBox;
        private readonly Button _apply;
        private readonly TextBox _codeBox;
        // FR-PROJ-07: when the designer is editing an on-disk config (pyproject.toml / standalone .toml),
        // this is its path so Save writes the model back via TomlWriter; null for a new in-memory document.
        private string _filePath;

        private const string Sample =
            "[project]\nname = \"myapp\"\nversion = \"0.1.0\"\nrequires-python = \">=3.12\"\n" +
            "dependencies = [\"numpy>=1.24\", \"requests\"]\n\n[tool.helixstudio]\nkind = \"app\"\ninterface-style = \"protocol\"\n";

        public TomlDesignerForm()
        {
            // These designer windows are plain Forms, so without this they fall back to the
            // WinForms default (Microsoft Sans Serif) instead of the shell UI font.
            Font = LunaFonts.Ui;
            Text = "TOML Designer";
            Width = 1040;
            Height = 660;
            StartPosition = FormStartPosition.CenterParent;

            var toolbar = new Panel { Dock = DockStyle.Top, Height = 32 };
            var addTable = new Button { Text = "Add Table", Location = new Point(6, 4), Width = 90 };
            addTable.Click += OnAddTable;
            var addKey = new Button { Text = "Add Key", Location = new Point(100, 4), Width = 80 };
            addKey.Click += OnAddKey;
            var remove = new Button { Text = "Remove", Location = new Point(184, 4), Width = 80 };
            remove.Click += OnRemove;
            // FR-PROJ-07: Open/Save make this a config editor for existing pyproject.toml / standalone .toml.
            var open = new Button { Text = "Open...", Location = new Point(272, 4), Width = 80 };
            open.Click += OnOpen;
            var save = new Button { Text = "Save", Location = new Point(356, 4), Width = 70 };
            save.Click += OnSave;
            toolbar.Controls.Add(addTable); toolbar.Controls.Add(addKey); toolbar.Controls.Add(remove);
            toolbar.Controls.Add(open); toolbar.Controls.Add(save);

            _tree = new TreeView { Dock = DockStyle.Fill, HideSelection = false };
            _tree.AfterSelect += OnSelect;
            var treePanel = new Panel { Dock = DockStyle.Left, Width = 320 };
            treePanel.Controls.Add(_tree);
            treePanel.Controls.Add(new Label { Text = "Document Tree", Dock = DockStyle.Top, Height = 20, Font = new Font(Font, FontStyle.Bold) });

            // Edit form (middle).
            var form = new Panel { Dock = DockStyle.Left, Width = 260, Padding = new Padding(8) };
            form.Controls.Add(new Label { Text = "Key", Location = new Point(8, 30), AutoSize = true });
            _keyBox = new TextBox { Location = new Point(8, 48), Width = 230 };
            form.Controls.Add(_keyBox);
            form.Controls.Add(new Label { Text = "Value", Location = new Point(8, 78), AutoSize = true });
            _valueBox = new TextBox { Location = new Point(8, 96), Width = 230 };
            form.Controls.Add(_valueBox);
            _apply = new Button { Text = "Apply", Location = new Point(8, 128), Width = 90, Enabled = false };
            _apply.Click += OnApply;
            form.Controls.Add(_apply);
            form.Controls.Add(new Label { Text = "Selected item", Dock = DockStyle.Top, Height = 20, Font = new Font(Font, FontStyle.Bold) });

            // TabStop=false keeps this read-only preview from being the initially-focused
            // control (a focused read-only TextBox selects its entire content, rendering the
            // whole generated listing as one blue block).
            _codeBox = new TextBox { Dock = DockStyle.Fill, Multiline = true, ReadOnly = true, ScrollBars = ScrollBars.Both, WordWrap = false, Font = new Font("Consolas", 9f), TabStop = false, HideSelection = true };
            var codePanel = new Panel { Dock = DockStyle.Fill };
            codePanel.Controls.Add(_codeBox);
            codePanel.Controls.Add(new Label { Text = "Generated TOML", Dock = DockStyle.Top, Height = 20, Font = new Font(Font, FontStyle.Bold) });

            Controls.Add(codePanel);
            Controls.Add(form);
            Controls.Add(treePanel);
            Controls.Add(toolbar);

            Rebuild();
        }

        public static void ShowSingleton(IWin32Window owner)
        {
            if (_instance == null || _instance.IsDisposed)
            {
                _instance = new TomlDesignerForm();
                _instance.FormClosed += delegate { _instance = null; };
                _instance.Show(owner);
            }
            else { _instance.BringToFront(); _instance.Activate(); }
        }

        /// <summary>
        /// FR-PROJ-07: open the graphical config editor on an existing <c>pyproject.toml</c> or standalone
        /// <c>.toml</c>. Parses the file into the document model and binds Save to write back via TomlWriter.
        /// </summary>
        public static void ShowForFile(IWin32Window owner, string path)
        {
            if (_instance == null || _instance.IsDisposed)
            {
                _instance = new TomlDesignerForm();
                _instance.FormClosed += delegate { _instance = null; };
                _instance.Show(owner);
            }
            else { _instance.BringToFront(); _instance.Activate(); }
            _instance.LoadFile(path);
        }

        /// <summary>Parse an on-disk .toml into the editor and remember its path for Save. Returns false on error.</summary>
        public bool LoadFile(string path)
        {
            if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path)) return false;
            try
            {
                _doc = TomlParser.Parse(System.IO.File.ReadAllText(path));
                _filePath = path;
                Text = "TOML Config Editor — " + System.IO.Path.GetFileName(path);
                Rebuild();
                return true;
            }
            catch { return false; }
        }

        /// <summary>Write the edited document back to its file via TomlWriter (comment/order preserving). </summary>
        public bool SaveFile()
        {
            if (string.IsNullOrEmpty(_filePath)) return false;
            try { System.IO.File.WriteAllText(_filePath, TomlWriter.Write(_doc) ?? string.Empty); return true; }
            catch { return false; }
        }

        private void OnOpen(object sender, EventArgs e)
        {
            using (var dlg = new OpenFileDialog { Filter = "TOML config (*.toml)|*.toml|All files (*.*)|*.*", Title = "Open TOML config" })
            {
                if (dlg.ShowDialog(this) == DialogResult.OK) LoadFile(dlg.FileName);
            }
        }

        private void OnSave(object sender, EventArgs e)
        {
            if (string.IsNullOrEmpty(_filePath))
            {
                using (var dlg = new SaveFileDialog { Filter = "TOML config (*.toml)|*.toml", Title = "Save TOML config", FileName = "pyproject.toml" })
                {
                    if (dlg.ShowDialog(this) != DialogResult.OK) return;
                    _filePath = dlg.FileName;
                }
            }
            SaveFile();
            Text = "TOML Config Editor — " + System.IO.Path.GetFileName(_filePath);
        }

        // A tree-node payload for an editable scalar: its owning table + key.
        private sealed class ValueRef { public TomlTable Owner; public string Key; public TomlValue Value; }

        private void Rebuild()
        {
            _tree.BeginUpdate();
            _tree.Nodes.Clear();
            var root = new TreeNode("(root)") { Tag = _doc.Root };
            _tree.Nodes.Add(root);
            AddTableNodes(root, _doc.Root);
            root.ExpandAll();
            _tree.EndUpdate();
            _codeBox.Text = (TomlWriter.Write(_doc) ?? string.Empty).Replace("\n", "\r\n");
        }

        private void AddTableNodes(TreeNode parent, TomlTable table)
        {
            foreach (string key in table.KeyOrder)
            {
                TomlItem item = table.Get(key);
                if (item is TomlTable sub)
                {
                    var n = new TreeNode("[" + key + "]") { Tag = sub, NodeFont = new Font(_tree.Font, FontStyle.Bold) };
                    parent.Nodes.Add(n);
                    AddTableNodes(n, sub);
                }
                else if (item is TomlTableArray arr)
                {
                    var n = new TreeNode("[[" + key + "]] (" + arr.Elements.Count + ")") { Tag = arr };
                    parent.Nodes.Add(n);
                    for (int i = 0; i < arr.Elements.Count; i++)
                    {
                        var en = new TreeNode("#" + i) { Tag = arr.Elements[i] };
                        n.Nodes.Add(en);
                        AddTableNodes(en, arr.Elements[i]);
                    }
                }
                else if (item is TomlValue v)
                {
                    string label = key + " = " + ValueLabel(v);
                    parent.Nodes.Add(new TreeNode(label) { Tag = new ValueRef { Owner = table, Key = key, Value = v } });
                }
            }
        }

        private static string ValueLabel(TomlValue v)
        {
            switch (v.Kind)
            {
                case TomlValueKind.String: return "\"" + v.StringValue + "\"";
                case TomlValueKind.Array: return "[…] (" + (v.Array != null ? v.Array.Count : 0) + ")";
                case TomlValueKind.InlineTable: return "{…}";
                default: return v.Raw;
            }
        }

        private void OnSelect(object sender, TreeViewEventArgs e)
        {
            var vr = e.Node != null ? e.Node.Tag as ValueRef : null;
            if (vr != null && vr.Value.Kind == TomlValueKind.String)
            {
                _keyBox.Text = vr.Key;
                _valueBox.Text = vr.Value.StringValue;
                _apply.Enabled = true;
                _apply.Tag = vr;
            }
            else
            {
                _keyBox.Text = _valueBox.Text = "";
                _apply.Enabled = false;
                _apply.Tag = null;
            }
        }

        private void OnApply(object sender, EventArgs e)
        {
            var vr = _apply.Tag as ValueRef;
            if (vr == null) return;
            vr.Value.StringValue = _valueBox.Text;
            vr.Value.Raw = "\"" + _valueBox.Text + "\"";
            // Rename key if changed.
            if (!string.IsNullOrEmpty(_keyBox.Text) && _keyBox.Text != vr.Key)
            {
                var owner = vr.Owner;
                if (!owner.Items.ContainsKey(_keyBox.Text))
                {
                    owner.Items.Remove(vr.Key);
                    int idx = owner.KeyOrder.IndexOf(vr.Key);
                    if (idx >= 0) owner.KeyOrder[idx] = _keyBox.Text;
                    owner.Items[_keyBox.Text] = vr.Value;
                    vr.Key = _keyBox.Text;
                }
            }
            Rebuild();
        }

        private TomlTable SelectedTable()
        {
            var n = _tree.SelectedNode;
            while (n != null)
            {
                if (n.Tag is TomlTable t) return t;
                var vr = n.Tag as ValueRef;
                if (vr != null) return vr.Owner;
                n = n.Parent;
            }
            return _doc.Root;
        }

        private void OnAddTable(object sender, EventArgs e)
        {
            string name = Prompt("New table name (e.g. build-system)");
            if (string.IsNullOrEmpty(name)) return;
            var target = _doc.Root;
            if (!target.Items.ContainsKey(name))
                target.Set(name, new TomlTable { ExplicitlyDefined = true });
            Rebuild();
        }

        private void OnAddKey(object sender, EventArgs e)
        {
            TomlTable t = SelectedTable();
            string key = Prompt("New key name");
            if (string.IsNullOrEmpty(key) || t.Items.ContainsKey(key)) return;
            t.Set(key, new TomlValue { Kind = TomlValueKind.String, StringValue = "value", Raw = "\"value\"" });
            Rebuild();
        }

        private void OnRemove(object sender, EventArgs e)
        {
            var n = _tree.SelectedNode;
            if (n == null) return;
            var vr = n.Tag as ValueRef;
            if (vr != null) { vr.Owner.Items.Remove(vr.Key); vr.Owner.KeyOrder.Remove(vr.Key); Rebuild(); return; }
            // Remove a table from the root (best-effort).
            if (n.Tag is TomlTable && n.Parent != null && n.Parent.Tag is TomlTable parent)
            {
                foreach (string k in new System.Collections.Generic.List<string>(parent.KeyOrder))
                    if (ReferenceEquals(parent.Get(k), n.Tag)) { parent.Items.Remove(k); parent.KeyOrder.Remove(k); break; }
                Rebuild();
            }
        }

        private string Prompt(string title)
        {
            using (var dlg = new LunaForm { Text = title, Width = 320, Height = 130, StartPosition = FormStartPosition.CenterParent, FormBorderStyle = FormBorderStyle.FixedDialog })
            {
                var tb = new TextBox { Dock = DockStyle.Top, Margin = new Padding(8) };
                var ok = new Button { Text = "OK", Dock = DockStyle.Bottom, DialogResult = DialogResult.OK };
                dlg.Controls.Add(tb); dlg.Controls.Add(ok); dlg.AcceptButton = ok;
                return dlg.ShowDialog(this) == DialogResult.OK ? tb.Text.Trim() : null;
            }
        }

        internal string GeneratedCode { get { return _codeBox.Text; } }
        internal int TableCount { get { int n = 0; foreach (var k in _doc.Root.KeyOrder) if (_doc.Root.Get(k) is TomlTable) n++; return n; } }
    }
}
